// ResourceConfigV030 is a migration wrapper around otelconf's config.Resource
// which adds support for the legacy inline resource attribute format, where
// resource attributes were specified as a map of string keys to nullable
// string values directly under the "resource" key.
//
// The embedded config.Resource is squashed, promoting its Attributes,
// SchemaUrl, Detectors, and AttributesList fields. Any keys that do not
// correspond to one of those known fields are captured into LegacyAttributes
// via the mapstructure ",remain" tag, representing the legacy inline format.
type ResourceConfigV030 struct {
	config.Resource `mapstructure:",squash"`

	// LegacyAttributes holds resource attributes specified using the legacy
	// inline map format. mapstructure only supports map[string]any for
	// ",remain" fields, but the values are expected to be equivalent to
	// map[string]*string: a string value overrides the corresponding attribute,
	// while a nil value removes the default attribute of that name.
	LegacyAttributes map[string]any `mapstructure:",remain"`
}

func (cfg *ResourceConfigV030) Unmarshal(conf *confmap.Conf) error {
	if err := conf.Unmarshal(cfg); err != nil {
		return err
	}
	// nil-valued legacy keys are used to remove default attributes, but they
	// must not be stored in the LegacyAttributes map itself.
	for key, val := range cfg.LegacyAttributes {
		if val == nil {
			delete(cfg.LegacyAttributes, key)
		}
	}
	return nil
}

func (cfg *ResourceConfigV030) Validate() error {
	if cfg.AttributesList != nil {
		return errors.New("resource::attributes_list is not currently supported")
	}
	for key, val := range cfg.LegacyAttributes {
		switch val.(type) {
		case nil, string:
		default:
			return fmt.Errorf("resource::%s: legacy inline resource attribute must be a string or null", key)
		}
	}
	if len(cfg.Attributes) > 0 && len(cfg.LegacyAttributes) > 0 {
		return errors.New("resource::attributes cannot be used together with legacy inline resource attributes")
	}
	return nil
