// errMissingCollectorResource is returned by the telemetry providers when the
// collector resource has not been initialized in the settings.
var errMissingCollectorResource = errors.New("collector resource must be initialized before creating telemetry providers")

// defaultAttributeValues returns the default resource attributes for the given
// build info. It is a variable so that it may be replaced in tests.
var defaultAttributeValues = func(buildInfo component.BuildInfo) (map[string]string, error) {
	instanceUUID, err := uuid.NewRandom()
	if err != nil {
		return nil, err
	}
	return map[string]string{
		string(semconv.ServiceNameKey):       buildInfo.Command,
		string(semconv.ServiceVersionKey):    buildInfo.Version,
		string(semconv.ServiceInstanceIDKey): instanceUUID.String(),
	}, nil
}

func createResource(
	ctx context.Context,
	set telemetry.Settings,
	componentConfig component.Config,
) (pcommon.Resource, error) {
	cfg := componentConfig.(*Config)
	resourceConfig, err := createInitialResourceConfig(set.BuildInfo, &cfg.Resource)
	if err != nil {
		return pcommon.Resource{}, err
	}

	// Use the otelconf SDK to resolve the resource attributes. This ensures
	// the typed attribute conversion behaves consistently with the SDK.
	sdk, err := config.NewSDK(
		config.WithContext(ctx),
		config.WithOpenTelemetryConfiguration(config.OpenTelemetryConfiguration{
			Resource: resourceConfig,
		}),
	)
	if err != nil {
		return pcommon.Resource{}, err
	}
	defer func() {
		_ = sdk.Shutdown(ctx)
	}()

	pcommonRes := pcommon.NewResource()
	if sdkRes := sdk.Resource(); sdkRes != nil {
		attrs := pcommonRes.Attributes()
		for _, keyValue := range sdkRes.Attributes() {
			putAttributeValue(attrs, string(keyValue.Key), keyValue.Value)
		}
	}
	return pcommonRes, nil
}

// createInitialResourceConfig builds the initial otelconf resource configuration
// from the build info defaults and the user-provided resource configuration.
func createInitialResourceConfig(buildInfo component.BuildInfo, cfg *migration.ResourceConfigV030) (*config.Resource, error) {
	defaults, err := defaultAttributeValues(buildInfo)
	if err != nil {
		return nil, err
	}

	res := &config.Resource{
		SchemaUrl:  cfg.SchemaUrl,
		Attributes: make([]config.AttributeNameValue, 0, len(defaults)+len(cfg.LegacyAttributes)+len(cfg.Attributes)),
	}

	// Add the default attributes, excluding any attribute names that were set
	// (overridden or removed with a nil value) in the legacy inline format.
	for name, value := range defaults {
		if _, ok := cfg.LegacyAttributes[name]; ok {
			continue
		}
		res.Attributes = append(res.Attributes, config.AttributeNameValue{Name: name, Value: value})
	}

	// Add the non-nil legacy attributes. A nil value indicates the corresponding
	// default attribute should be removed, so it is not added here.
	for name, value := range cfg.LegacyAttributes {
		if value == nil {
			continue
		}
		res.Attributes = append(res.Attributes, config.AttributeNameValue{Name: name, Value: value})
	}

	// Add the declarative attributes.
	res.Attributes = append(res.Attributes, cfg.Attributes...)

	return res, nil
}

// createFixedResourceConfig converts an already-resolved pcommon.Resource into
// an otelconf resource configuration, carrying over the SchemaUrl from the
// resource configuration.
func createFixedResourceConfig(cfg *migration.ResourceConfigV030, res *pcommon.Resource) (*config.Resource, error) {
	if res == nil {
		return nil, errMissingCollectorResource
	}

	// SchemaUrl is not exposed by pcommon.Resource, so it is carried over from
	// the resource configuration.
	resourceConfig := &config.Resource{
		SchemaUrl:  cfg.SchemaUrl,
		Attributes: make([]config.AttributeNameValue, 0, res.Attributes().Len()),
	}
	res.Attributes().Range(func(k string, v pcommon.Value) bool {
		resourceConfig.Attributes = append(resourceConfig.Attributes, config.AttributeNameValue{
			Name:  k,
			Value: v.AsRaw(),
		})
		return true
	})
	return resourceConfig, nil
}

// putAttributeValue stores an OpenTelemetry attribute value into a pcommon.Map,
// preserving its type.
func putAttributeValue(m pcommon.Map, k string, v attribute.Value) {
	switch v.Type() {
	case attribute.BOOL:
		m.PutBool(k, v.AsBool())
	case attribute.INT64:
		m.PutInt(k, v.AsInt64())
	case attribute.FLOAT64:
		m.PutDouble(k, v.AsFloat64())
	default:
		m.PutStr(k, v.AsString())
	}
}

// pcommonAttrsToOTelAttrs gets the Resource attributes to OpenTelemetry attribute.KeyValue slice.
func pcommonAttrsToOTelAttrs(resource *pcommon.Resource) []attribute.KeyValue {
	var result []attribute.KeyValue
	if resource != nil {
		attrs := resource.Attributes()
		attrs.Range(func(k string, v pcommon.Value) bool {
			result = append(result, attribute.String(k, v.AsString()))
			return true
		})
	}
	return result
}
